INSERT INTO `career_job_posts` (`id`, `career_department_id`, `career_designation_id`, `prefix_id`, `job_title`, `job_type`, `vacancy`, `experience`, `location`, `salary`, `job_description`, `deadline`, `status`, `slug_job_title`, `created_at`, `updated_at`) VALUES
(13, 10, 48, 'webns-bus-exe-2024-apr-21', 'Executive / Sr. Executive for Business Development WEBNS Technology Ltd.', 'Full Time', 'Not Specified', '2-4 years', 'Anywhere in Bangladesh', 'Negotiable', '<p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">WEBNS Technology Ltd. looking for an ambitious, energetic, and highly-motivated Executive/Sr. Executive for Business Development department who will deal mainly with corporate B2B software sales &amp; marketing. This is a busy role where each day can bring a new set of objectives, priorities, and demands. This is a demanding and fast-moving position that requires someone who can exercise discretion, good judgment, and initiative. The successful candidate will be self-motivated, quick-thinking, and flexible and be able to juggle multiple and diverse responsibilities with a strong emphasis on organization and unwavering attention to detail at all times.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><br><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>BROAD SPECTRUM OF DUTIES &amp; RESPONSIBILITIES:</u></strong></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><u1:p></u1:p>The Executive/Sr. Executive supports business development efforts by securing new business opportunities.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Assist to identify and execute new opportunities in local markets that will enhance the product offerings and deliver incremental revenue and profit.</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><u1:p></u1:p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Conduct research to identify new local business development opportunities in local markets including identifying new potential partners or acquisitions for the business.</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><u1:p></u1:p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Sells products by establishing contact and developing relationships with prospects; recommending solutions.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Maintains relationships with clients by providing support, information, and guidance; researching and recommending new opportunities; and recommending profit and service improvements.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Securing introductory or follow-up meetings and proactively working with the business development team in lead generation development.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Manage the communication for the organization with prospective clients via means like emails, telephones, and websites.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Respond to inquiries made by prospective clients about company products in a timely and friendly manner.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Contributes to team effort by accomplishing related results as needed.</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>EXPERIENCE:</u></strong></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin-left:0in;margin-right:0in;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><u1:p></u1:p>2-4 years of proven Corporate Sales &amp; Marketing experience preferably in software marketing.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>QUALIFICATION:</u></strong>&nbsp;</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-bottom:.0001pt;margin-right:0in;margin-top:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Education in any field, however, a post-graduation is a must.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><strong><u>SALARY:</u></strong><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-bottom:.0001pt;margin-right:0in;margin-top:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Attractive Salary Package with other benefits.</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><br><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>LOCATION:</u></strong>&nbsp;</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Anywhere in Bangladesh<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><br><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>KEY COMPETENCIES:</u></strong></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><u1:p></u1:p>Age 25 to 33 years<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">The job will require regular client (B2B) visits per day.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Applicants having hands-on experience in B2B sales will be preferred.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Must be proactive, smart, self-motivated<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Must have an aggressive selling attitude<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Should have skills in business communication<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Should have good presentation skills<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Good skills in Word, Excel, PowerPoint, e-mail, Web browsing<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Must be prepared to work under pressure<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Should be good in written &amp; spoken English<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>OTHER BENEFITS:</u></strong></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><u1:p></u1:p>Mobile bills, TA/DA as per company policy.</span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Festival bonus, Gratuity, and Provident Fund.<u1:p></u1:p><u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul>', '2024-05-31', 'Publish', 'executive-sr-executive-for-business-development-webns-technology-ltd', '2024-04-21 12:52:11', '2024-04-21 12:52:11'),
(14, 10, 49, 'webns-bus-man-2024-apr-21', 'Manager / Assistant Manager Business Development WEBNS Technology Ltd.', 'Full Time', 'Not Specified', '7 - 8 years', 'Anywhere in Bangladesh', 'Negotiable', '<p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">WEBNS Technology Ltd. looking for an ambitious, energetic, and efficient Business Development Manager/Assistant Manager who will take us further in the world of growing software business by expanding our clientele and creating new business strategies. He/she will also be responsible for supervising and leading our sales &amp; marketing team. You will be at the front of the company and will have&nbsp;the dedication to explore new promising clients and create and apply an effective sales strategy by supervising and organizing our sales &amp; marketing team.&nbsp;<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>Duties &amp; Responsibilities:</u></strong></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><u1:p></u1:p>Understand our ideal customers and how they relate to our products.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Managing organizational sales by developing a business/strategic plan that covers sales, revenue, and expense controls.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Maximizing the sales team\'s potential, crafting sales plans, and justifying those plans to the upper management.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Overseeing the activities and performance of your sales team by tracking sales goals, and setting individual sales targets.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Facilitate the training of your sales team.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Preparing strategic plans for marketing through digital platforms and taking the initiative to execute the plan within a specific time.&nbsp;<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Meeting planned marketing &amp; sales goals for both physical and digital marketing.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Build a strong relationship with clients (B2B, B2C).<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Exploring new prospective clients&nbsp;</span><span style=\"font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">to enhance WEBNS product recognition in the local area</span><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Researching organizations and individuals to find new opportunities.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Finding and developing new markets and improving software sales.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Developing your sales team through motivation, counseling, and product knowledge education.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Promoting the organization and its products.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li><li style=\"margin-right:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\">Developing quotes and proposals for clients.<u1:p></u1:p></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p></li></ul><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"color:black;font-family:&quot;Arial&quot;,sans-serif;font-size:12pt;\"><strong><u>Experience</u></strong><u>:&nbsp;</u></span><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\"><o:p></o:p></span></p><p style=\"margin:0in 0in .0001pt;text-align:justify;\"><span style=\"font-family:&quot;Times New Roman&quot;, serif;font-size:12pt;\">&nbsp;<o:p></o:p></span></p><ul><li style=\"margin-bottom:.0001pt;margin-right:0in;margin-top:0in;tab-stops:list .5in;\"><p style=\"text-align:justify;\"><span style=\"font-family:Symbol;font-size:10.0pt;\"><u1:p></u1:p></span><span style=\"color:black;font-fa